let legacyCustomLessonsForMigration = (()=>{try{const v=JSON.parse(localStorage.getItem("draftwise.customLessons.v1")||"[]");return Array.isArray(v)?v.filter(l=>l&&typeof l.id==="string"&&Array.isArray(l.essay)):[]}catch{return []}})();
