function applyLibraryLessons(){
  LESSONS.splice(BUILTIN_LESSON_COUNT);
  const seen=new Set(LESSONS.slice(0,BUILTIN_LESSON_COUNT).map(l=>l.id));
  [...globalLessons,...customLessons].forEach(l=>{
    if(l && typeof l.id==="string" && Array.isArray(l.essay) && !seen.has(l.id)){
      seen.add(l.id); LESSONS.push(l);
    }
  });
}
