function renderLessonMeta(){const h=document.querySelector(".task-card h2");if(h)h.textContent=currentLesson.question;const visual=$("taskVisual");if(visual){const src=currentLesson.visualData||currentLesson.visual||"";visual.hidden=!src;visual.innerHTML=src?`<img src="${escapeHtml(src)}" alt="Hình minh họa đề ${escapeHtml(currentLesson.title)}" loading="lazy">`:"";if(visual&&src){const image=visual.querySelector("img");image?.addEventListener("error",()=>{image.hidden=true;let note=visual.querySelector(".visual-fallback");if(!note){note=document.createElement("p");note.className="visual-fallback";note.textContent="Không tải được hình trực tiếp từ máy chủ DOL. ";const link=document.createElement("a");link.href=currentLesson.sourceUrl||"#";link.target="_blank";link.rel="noopener noreferrer";link.textContent="Mở đề gốc để xem hình";note.appendChild(link);visual.appendChild(note)}},{once:true})}}const tags=document.querySelector(".task-tags");if(tags)tags.innerHTML=`<span class="tag dark">WRITING ${escapeHtml(currentLesson.task.toUpperCase())}</span><span class="tag">${escapeHtml(currentLesson.topic)}</span><span class="tag">${escapeHtml(currentLesson.type)}</span>`;const meta=document.querySelector(".task-meta");if(meta)meta.innerHTML=`<span>◷ Gợi ý thời gian: ${currentLesson.time} phút</span><span>◎ ${escapeHtml(currentLesson.sourceType==="official-format"?"Đề tự biên soạn theo format IELTS.org / British Council":(String(currentLesson.source||"").toLowerCase().includes("original practice")?"Bài luyện tự biên soạn; liên kết chỉ để tham khảo":currentLesson.source))}</span><span>↗ <a href="${escapeHtml(currentLesson.sourceUrl)}" target="_blank" rel="noreferrer">Mở nguồn tham khảo</a></span>`;const heading=document.querySelector("#practiceView .page-heading h1");if(heading)heading.innerHTML=practiceMode==="independent"?`Tự viết IELTS, <em>${escapeHtml(currentLesson.title)}.</em>`:`Luyện viết, <em>${escapeHtml(currentLesson.title)}.</em>`;const iq=$("independentQuestionText");if(iq)iq.textContent=currentLesson.question;const isTask1=String(currentLesson.task).toLowerCase().includes("task 1");if($("independentTaskLabel"))$("independentTaskLabel").textContent=isTask1?"Writing Task 1 Academic":"Writing Task 2";if($("independentTimeLabel"))$("independentTimeLabel").textContent=(isTask1?"20":"40")+" phút gợi ý";if($("independentTargetWords"))$("independentTargetWords").textContent=isTask1?"150+":"250+";if($("independentWordGuidance"))$("independentWordGuidance").textContent=isTask1?"Tối thiểu nên viết 150 từ":"Tối thiểu nên viết 250 từ";}
