function switchView(view){
  const views=["library","practice","history","mistakes","settings","personalLessons","adminLessons","adminSettings"];
  views.forEach(v=>{const el=$(v+"View");if(el)el.hidden=v!==view;});
  document.querySelectorAll(".nav-item[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));
  const labels={library:"Thư viện đề",practice:"Luyện dịch ngược",history:"Lịch sử bài làm",mistakes:"Sổ tay lỗi sai",settings:"Cài đặt tài khoản",personalLessons:"Quản lý đề của tôi",adminLessons:"Quản lý thư viện",adminSettings:"Bảo mật web"};
  const crumb=$("breadcrumbCurrent");if(crumb)crumb.textContent=labels[view]||"WriteWiser";
  if(view==="library"){
    if(libraryLoadState==="ready" && Date.now()-lastLibrarySyncAt>15000) loadServerLessons();
    else renderLibrary();
  }
  if(view==="history")renderHistory();
  if(view==="mistakes")renderMistakes();
  if(view==="settings"){updateSettingsAccess();}
  if(view==="personalLessons"){updatePersonalLessonsAccess();renderPersonalLessons();}
  if(view==="adminLessons"||view==="adminSettings"){
    if(!currentUser||currentUser.role!=="admin"){showToast("Trang này chỉ dành cho tài khoản admin.");switchView("library");return;}
    if(view==="adminLessons")renderAdminBuiltinLessons();
  }
  window.scrollTo({top:0,behavior:"smooth"});
}
function switchPracticeMode(mode){
  practiceMode=mode==="independent"?"independent":"reverse";
  const reverse=practiceMode==="reverse";
  $("reverseModePanel").hidden=!reverse;
  $("independentModePanel").hidden=reverse;
  $("reverseModeButton").classList.toggle("active",reverse);
  $("independentModeButton").classList.toggle("active",!reverse);
  $("reverseModeButton").setAttribute("aria-selected",String(reverse));
  $("independentModeButton").setAttribute("aria-selected",String(!reverse));
  const sharedQuestion=document.querySelector(".task-card h2");if(sharedQuestion)sharedQuestion.hidden=!reverse;
  const sharedMeta=document.querySelector(".task-card .task-meta");if(sharedMeta)sharedMeta.hidden=!reverse;
  const resetButton=$("resetButton");if(resetButton)resetButton.hidden=!reverse;
  $("independentQuestionText").textContent=currentLesson.question;
  const isTask1=String(currentLesson.task).toLowerCase().includes("task 1");
  $("independentTaskLabel").textContent=isTask1?"Writing Task 1 Academic":"Writing Task 2";
  $("independentTimeLabel").textContent=(isTask1?"20":"40")+" phút gợi ý";
  $("independentTargetWords").textContent=isTask1?"150+":"250+";
  $("independentWordGuidance").textContent=isTask1?"Tối thiểu nên viết 150 từ":"Tối thiểu nên viết 250 từ";
  if(!reverse){
    const draft=independentDrafts[currentLesson.id];
    if(typeof draft==="string" && $("independentEssayInput").value.trim()==="")$("independentEssayInput").value=draft;
    updateIndependentMeta();independentStart=Date.now();
  }
  const heading=document.querySelector("#practiceView .page-heading h1");
  if(heading)heading.innerHTML=reverse?`Luyện viết, <em>${escapeHtml(currentLesson.title)}.</em>`:`Tự viết IELTS, <em>${escapeHtml(currentLesson.title)}.</em>`;
  const intro=document.querySelector("#practiceView .page-heading p");if(intro)intro.textContent=reverse?"Đọc toàn bộ bản dịch. Tự viết tiếng Anh. Chỉ xem kết quả khi bạn nộp cả bài.":"Không có bản dịch hoặc câu mẫu. Tự viết bài hoàn chỉnh rồi nộp để nhận phản hồi theo bốn tiêu chí IELTS.";
}
function updateIndependentMeta(){
  const text=$("independentEssayInput").value;
  $("independentWordCount").textContent=wordCount(text);
  const elapsed=Math.max(0,Math.floor((Date.now()-independentStart)/1000));
  $("independentTimeSpent").textContent=`Thời gian phiên: ${String(Math.floor(elapsed/60)).padStart(2,"0")}:${String(elapsed%60).padStart(2,"0")}`;
}
