function makeIndependentPrompt(record){
 const isTask1=record.task==="Task 1";
 return `Bạn là giám khảo luyện thi IELTS Writing. Hãy chấm bài độc lập theo 4 tiêu chí và band descriptors IELTS công khai, không phải bài dịch. Đây là ước lượng học tập, không phải điểm IELTS chính thức.\n\nTÓM TẮT RUBRIC: ${isTask1?"Task Achievement (overview, chọn lọc đặc điểm chính, dữ liệu/so sánh chính xác)":"Task Response (trả lời mọi phần của đề, lập trường rõ, phát triển ý và hỗ trợ lập luận)"}; Coherence and Cohesion (tổ chức, tiến triển, liên kết); Lexical Resource (phạm vi, độ chính xác, collocation); Grammatical Range and Accuracy (đa dạng và kiểm soát cấu trúc). Band 6: đáp ứng phần chính nhưng phát triển/độ chính xác còn hạn chế; Band 7: rõ, có phát triển và linh hoạt khá tốt; Band 8: đầy đủ, mạch lạc, từ vựng và cấu trúc linh hoạt, phần lớn chính xác; Band 9: rất sâu sắc, tự nhiên, chính xác và gần như không lỗi. Ví dụ hiệu chuẩn ngắn tự soạn, không phải bài mẫu IELTS chính thức: B6 “Public transport is useful because it helps people go to work.”; B7 “Reliable public transport can reduce commuting costs and ease congestion.”; B8 “A dependable network can lower travel costs while easing congestion, provided that services are frequent.”; B9 “When frequent, well-integrated services offer a viable alternative to driving, cities can curb congestion without restricting mobility.” Không so khớp bài với các ví dụ này; chúng chỉ minh họa độ chín của diễn đạt.\n\nTASK: ${record.task}\nĐỀ BÀI: ${record.question}\nBÀI VIẾT (${record.words} từ):\n${record.essayText}\n\nYêu cầu: chấm nghiêm công bằng; trả band cho đúng 4 tiêu chí, giải thích kèm dẫn chứng nguyên văn, nêu lỗi ưu tiên, nhận xét từng đoạn, viết phiên bản nâng cấp giữ nguyên ý, đưa 3 bước luyện tập. MỨC ĐỘ CHI TIẾT CAO: với MỖI tiêu chí hãy có các mục "Điểm tốt", "Điểm cần cải thiện", ít nhất 2–4 dẫn chứng chính xác lấy từ bài (nếu có đủ bằng chứng), giải thích vì sao đáp ứng/chưa đáp ứng descriptor ở band đó và vì sao chưa lên band kế tiếp; đề xuất câu thay thế cụ thể và giải thích ý nghĩa/độ chính xác. Với Task 1, đối chiếu từng nhận định với dữ liệu/ảnh đề; phân biệt tỷ trọng với tổng lượng tuyệt đối; kiểm tra overview có bao quát mọi biểu đồ; không bịa dữ liệu. Nếu ảnh đề được cung cấp, hãy phân tích ảnh và nêu rõ dữ liệu quan sát được; nếu không có ảnh, nói rõ hạn chế. Phân tích câu/đoạn cụ thể, không dùng lời khen chung chung. Schema criteria hỗ trợ strengths[], weaknesses[], evidence[], improvements[], next_band_gap; paragraph_feedback chi tiết; priority_errors có original, correction, explanation, criterion. Giữ nhận xét đủ chi tiết để người học biết chính xác phải sửa gì, không chỉ liệt kê lỗi ngắn. Task 1 thường cần 150+ từ; Task 2 thường cần 250+ từ. Không tự bịa số liệu. Hãy trình bày rõ ràng bằng tiếng Việt, dùng bullet. Nếu API tự động có thể trả JSON, hãy dùng schema: overall_band, criteria[{name,band,rationale,evidence[],improvements[]}], overall_summary, strengths[], priority_errors[{original,correction,explanation}], paragraph_feedback[{paragraph,comment,suggestions[]}], upgraded_version, next_steps[], caveat.`;
}
function renderIndependentFeedback(feedback,record){
 const criteria=Array.isArray(feedback.criteria)?feedback.criteria:[];
 const criteriaHtml=criteria.map(c=>`<article class="band-criterion"><h4>${escapeHtml(c.name||"Tiêu chí")} · Band ${escapeHtml(c.band??"—")}</h4><p>${escapeHtml(c.rationale||"")}</p>${Array.isArray(c.strengths)&&c.strengths.length?`<h5>Điểm tốt</h5><ul>${c.strengths.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}${Array.isArray(c.evidence)&&c.evidence.length?`<p class="band-evidence"><strong>Dẫn chứng cụ thể:</strong> ${c.evidence.map(escapeHtml).join(" · ")}</p>`:""}${Array.isArray(c.weaknesses)&&c.weaknesses.length?`<h5>Điểm cần cải thiện</h5><ul>${c.weaknesses.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}${Array.isArray(c.improvements)&&c.improvements.length?`<h5>Cách cải thiện cụ thể</h5><ul>${c.improvements.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}${c.next_band_gap?`<p><strong>Vì sao chưa lên band tiếp theo:</strong> ${escapeHtml(c.next_band_gap)}</p>`:""}</article>`).join("");
 const strengths=(feedback.strengths||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join("");
 const errors=(feedback.priority_errors||[]).map((e,i)=>`<article class="band-correction"><h4>Lỗi ưu tiên ${i+1}</h4><p><strong>Bạn viết:</strong> <span class="ai-error-highlight">${escapeHtml(e.original||"")}</span></p><p><strong>Đề xuất:</strong> ${escapeHtml(e.correction||"")}</p><p>${escapeHtml(e.explanation||"")}</p></article>`).join("");
 const paragraphs=(feedback.paragraph_feedback||[]).map(p=>`<article class="band-criterion"><h4>${escapeHtml(p.paragraph||"Đoạn văn")}</h4><p>${escapeHtml(p.comment||"")}</p>${Array.isArray(p.suggestions)&&p.suggestions.length?`<ul>${p.suggestions.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}</article>`).join("");
 const steps=(feedback.next_steps||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join("");
 return `<section class="ai-feedback"><div class="eyebrow">INDEPENDENT WRITING REVIEW</div><h2>Ước lượng Overall Band ${escapeHtml(feedback.overall_band??"—")}</h2><p>${escapeHtml(feedback.overall_summary||"Đã phân tích bài viết.")}</p><div class="band-overview"><div class="band-score-card overall"><strong>${escapeHtml(feedback.overall_band??"—")}</strong><span>Overall ước lượng</span></div>${criteria.map(c=>`<div class="band-score-card"><strong>${escapeHtml(c.band??"—")}</strong><span>${escapeHtml(c.name||"")}</span></div>`).join("")}</div><p><strong>Số từ:</strong> ${escapeHtml(feedback.word_count??record.words)} từ. ${escapeHtml(feedback.caveat||"Điểm chỉ mang tính tham khảo, không phải điểm IELTS chính thức.")}</p>${strengths?`<h3>Điểm mạnh</h3><ul>${strengths}</ul>`:""}<h3>Phân tích theo 4 tiêu chí</h3><div class="band-criterion-list">${criteriaHtml}</div>${errors?`<h3>Lỗi cần ưu tiên sửa</h3><div class="band-correction-list">${errors}</div>`:""}${paragraphs?`<h3>Nhận xét theo đoạn</h3><div class="band-criterion-list">${paragraphs}</div>`:""}${feedback.upgraded_version?`<h3>Phiên bản nâng cấp tham khảo</h3><div class="band-rewrite">${escapeHtml(feedback.upgraded_version)}</div>`:""}${steps?`<h3>Ba bước tiếp theo</h3><ul>${steps}</ul>`:""}<section class="feedback-calibration-editor"><h3>Hiệu chỉnh kết quả chấm</h3><p>Chỉnh JSON bên dưới nếu bạn thấy AI chấm sai. Bản sửa được lưu riêng trong tài khoản và có thể được admin xem xét để đưa vào hiệu chuẩn chung; người dùng thường không tự thay đổi rubric toàn hệ thống.</p><label for="correctedFeedbackJson">Kết quả chấm đã hiệu chỉnh (JSON)</label><textarea id="correctedFeedbackJson" rows="14">${escapeHtml(JSON.stringify(feedback,null,2))}</textarea><label for="calibrationReason">Lý do hiệu chỉnh / căn cứ descriptor</label><textarea id="calibrationReason" rows="3" placeholder="Ví dụ: TA bị chấm cao vì bài suy luận tổng lượng nước từ tỷ trọng…"></textarea><button type="button" class="button primary" id="saveFeedbackCorrectionButton">Lưu hiệu chỉnh</button><p id="feedbackCorrectionStatus" class="import-status" role="status"></p></section><p class="ai-disclaimer">Band do AI ước lượng dựa trên bài nộp và rubric tóm tắt. Kết quả không thay thế đánh giá của giám khảo IELTS được chứng nhận.</p></section>`;
}
async function getCurrentLessonImageData(){
 const src=currentLesson?.visualData||currentLesson?.visual||"";if(!src)return "";
 try{
  let url=src;if(!/^data:image\//i.test(src)){const response=await fetch(src,{credentials:"same-origin"});if(!response.ok)return "";const blob=await response.blob();url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(blob)});}
  if(url.startsWith("data:image/png;"))return url;
  return await new Promise(resolve=>{const img=new Image();img.onload=()=>{try{const canvas=document.createElement("canvas");canvas.width=img.naturalWidth||1200;canvas.height=img.naturalHeight||800;canvas.getContext("2d").drawImage(img,0,0);resolve(canvas.toDataURL("image/png"));}catch{resolve("")}};img.onerror=()=>resolve("");img.src=url;});
 }catch{return ""}
}
