 const types=[...new Set(pool.map(l=>l.type).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"vi"));
 const topics=[...new Set(pool.filter(l=>priorType==="all"||l.type===priorType).map(l=>l.topic).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"vi"));
 typeEl.innerHTML='<option value="all">Tất cả dạng bài</option>'+types.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join("");
 typeEl.value=types.includes(priorType)?priorType:"all";
 const validTopics=[...new Set(pool.filter(l=>typeEl.value==="all"||l.type===typeEl.value).map(l=>l.topic).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"vi"));
 topicEl.innerHTML='<option value="all">Tất cả chủ đề</option>'+validTopics.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join("");
