function splitEnglishSentences(text){
 const normalized=String(text||"").replace(/\r/g,"\n").trim();
 if(!normalized)return [];
 const protectedText=normalized.replace(/\b(e\.g|i\.e|Mr|Mrs|Ms|Dr|Prof|No|etc)\./gi,"$1<DOT>");
 return protectedText.split(/(?<=[.!?])\s+(?=[“\"‘'([{A-Z0-9])/).map(x=>x.replace(/<DOT>/g,".").replace(/\s*\n\s*/g," ").trim()).filter(Boolean);
}
function splitEnglishParagraphGroups(text){
 const normalized=String(text||"").replace(/\r/g,"").trim();if(!normalized)return [];
 const blocks=normalized.split(/\n\s*\n+/).map(x=>x.trim()).filter(Boolean);
 return blocks.map(block=>splitEnglishSentences(block.replace(/\n+/g," "))).filter(group=>group.length);
}
function parseTranslationParagraphGroups(text){
 const normalized=String(text||"").replace(/\r/g,"").trim();if(!normalized)return [];
 return normalized.split(/\n\s*\n+/).map(block=>block.split("\n").map(line=>line.trim().replace(/^\s*(?:\d+[.)、:-]|[-*•])\s*/,"").trim()).filter(Boolean)).filter(group=>group.length);
}
function formatGroupedLines(groups, prefixNumbers=false){
 let count=0;return groups.map(group=>group.map(line=>{count++;return prefixNumbers?`${count}. ${line}`:line;}).join("\n")).join("\n\n");
}
function essayTextByParagraph(essay,key){
 const groups=[];for(const item of (Array.isArray(essay)?essay:[])){const index=paragraphIndexFor(item,0);while(groups.length<=index)groups.push([]);groups[index].push(String(item?.[key]||""));}
 return groups.filter(group=>group.length).map(group=>group.join("\n")).join("\n\n");
}
function pairEnglishAndVietnamese(englishText,vietnameseText,hintsText=""){
 const enGroups=splitEnglishParagraphGroups(englishText),en=enGroups.flat();const viGroups=parseTranslationParagraphGroups(vietnameseText),vi=viGroups.flat();
 if(!en.length)throw new Error("Hãy nhập bài mẫu tiếng Anh trước.");
 if(en.length!==vi.length)throw new Error(`Đã tách ${en.length} câu tiếng Anh nhưng có ${vi.length} câu tiếng Việt. Hãy giữ đúng số câu và thứ tự.`);
 const hints=parseTranslationParagraphGroups(hintsText).flat();let cursor=0;const essay=[];
 enGroups.forEach((group,paragraphIndex)=>group.forEach(text=>{essay.push({en:text,vi:vi[cursor],hint:hints[cursor]||"",paragraphIndex});cursor++;}));
 return essay;
}
function groupFlatItemsBySizes(items,sizes){let cursor=0;return sizes.map(size=>{const group=items.slice(cursor,cursor+size);cursor+=size;return group;});}
function assignParagraphGroupsToTextareas(englishId,vietnameseId,groups){
 const english=$(englishId),vietnamese=$(vietnameseId);const oldEnglishGroups=splitEnglishParagraphGroups(english?.value||"");const allSentences=oldEnglishGroups.flat();
 const valid=Array.isArray(groups)&&groups.length&&groups.every(g=>Array.isArray(g)&&g.length)&&groups.flat().length===allSentences.length;
 if(!valid)throw new Error("AI tách đoạn trả về nhóm câu không hợp lệ. Hãy thử lại.");
 const seen=groups.flat();if(seen.some(i=>!Number.isInteger(i)||i<0||i>=allSentences.length)||new Set(seen).size!==allSentences.length||seen.some((v,i)=>v!==i))throw new Error("AI tách đoạn làm mất, lặp hoặc đổi thứ tự câu. Không áp dụng thay đổi; hãy thử lại.");
 english.value=groups.map(g=>g.map(i=>allSentences[i]).join("\n")).join("\n\n");
 if(vietnamese&&vietnamese.value.trim()){
   const vi=parseTranslationParagraphGroups(vietnamese.value).flat();
   if(vi.length===allSentences.length)vietnamese.value=groups.map(g=>g.map(i=>vi[i]).join("\n")).join("\n\n");
 }
}
async function aiSegmentParagraphs(englishId,vietnameseId,statusId,buttonId){
 const english=$(englishId),status=$(statusId),button=$(buttonId);const groups=splitEnglishParagraphGroups(english?.value||"");const sentences=groups.flat();
 if(!sentences.length)throw new Error("Hãy nhập bài mẫu tiếng Anh trước khi tách đoạn.");
 if(sentences.length<2){status.textContent="Bài hiện chỉ có một câu, chưa cần tách đoạn.";return;}
 button.disabled=true;const label=button.textContent;button.textContent="AI đang tách đoạn…";status.textContent="AI đang phân nhóm câu theo mạch ý. Hãy rà soát trước khi lưu.";
 try{const result=await api("/api/segment-paragraphs",{method:"POST",body:JSON.stringify({sentences})});assignParagraphGroupsToTextareas(englishId,vietnameseId,result.groups);status.textContent=`AI đã chia ${sentences.length} câu thành ${(result.groups||[]).length} đoạn bằng ${result.model||"AI"}. Rà soát các dòng trống trước khi lưu.`;}
 finally{button.disabled=false;button.textContent=label;}
}
function buildTranslationPrompt(sentences){
 return `Hãy dịch các câu IELTS Writing sau sang tiếng Việt tự nhiên, chính xác, phù hợp văn phong học thuật.\nGiữ nguyên số thứ tự và số lượng câu; mỗi câu tiếng Việt nằm trên đúng một dòng; không thêm giải thích, không gộp hoặc tách câu.\n\n${sentences.map((s,i)=>`${i+1}. ${s}`).join("\n")}`;
}
function parseTranslationLines(text){
 return String(text||"").split(/\r?\n/).map(line=>line.trim().replace(/^\s*(?:\d+[.)、:-]|[-*•])\s*/,"").trim()).filter(Boolean);
}
