 if(!/^https:\/\/(tuhoc\.dolenglish\.vn|www\.dolenglish\.vn|dolenglish\.vn|dolacademy\.vn|www\.dolacademy\.vn)\//i.test(sourceUrl)&&sourceUrl)throw new Error("Đường dẫn nguồn nên là trang HTTPS của DOL. Nếu chưa có, hãy để trống.");
