const importFileInput = $("importFileInput");
importFileInput?.addEventListener("change",async()=>{
 const file=importFileInput.files?.[0]; if(!file)return;
 try{
   if(file.size>2_000_000)throw new Error("Tệp vượt quá 2 MB. Hãy dùng bài nhỏ hơn hoặc dán văn bản trực tiếp.");
   let body={filename:file.name};
   if(/\.docx$/i.test(file.name)){const bytes=new Uint8Array(await file.arrayBuffer());let binary="";for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));body.base64=btoa(binary)}
   else body.text=await file.text();
   const parsed=await api("/api/parse-import",{method:"POST",body:JSON.stringify(body)});
   if(parsed.kind==="bulk-json"&&Array.isArray(parsed.lessons)){
     if(!currentUser)throw new Error("Hãy đăng nhập trước khi lưu/import đề.");
     let count=0; for(const item of parsed.lessons){const lesson=normaliseBulkLesson(item);if(lesson){
       if(currentUser.role==="admin"){const result=await api("/api/global-lessons",{method:"POST",body:JSON.stringify({lesson})});globalLessons.push(result.lesson)}
       else customLessons.push({...lesson,source:"Bài tự nhập · riêng tài khoản",sourceType:"personal",custom:true,publishedGlobal:false}); count++;
     }}
     applyLibraryLessons();if(currentUser.role!=="admin")await persistAccountStateNow();renderLibrary();$("importStatus").textContent=currentUser.role==="admin"?`Đã xuất bản ${count} bài cho mọi tài khoản.`:`Đã lưu ${count} bài riêng trong tài khoản này.`;showToast(`Đã lưu ${count} bài.`);return;
   }
   const text=parsed.text||"";const meta=parsed.meta||{};
   if(meta.title&&!$("importTitle").value)$("importTitle").value=meta.title;
   if(meta.question&&!$("importQuestion").value)$("importQuestion").value=meta.question;
   $("importEnglish").value=text;
   $("importStatus").textContent=`Đã đọc ${file.name}. Hãy kiểm tra nội dung, bổ sung đề bài và nhấn “Dịch bằng AI” để tạo bản dịch câu đối câu.`;
 }catch(err){$("importStatus").textContent="Không đọc được tệp: "+err.message}
});
function normaliseBulkLesson(item){
 if(!item||typeof item!=="object")return null;
 const task=item.task==="Task 1"?"Task 1":"Task 2";let essay=Array.isArray(item.essay)?item.essay:[];
 if(!essay.length&&typeof item.english==="string"&&Array.isArray(item.vietnamese)){const groups=splitEnglishParagraphGroups(item.english);let idx=0;essay=groups.flatMap((g,paragraphIndex)=>g.map(en=>({en,vi:String(item.vietnamese[idx++]||""),hint:"",paragraphIndex}))) }
 essay=essay.filter(x=>x&&typeof x.en==="string"&&typeof x.vi==="string").map((x,i)=>({...x,paragraphIndex:Number.isInteger(x.paragraphIndex)&&x.paragraphIndex>=0?x.paragraphIndex:0}));if(!item.title||!item.question||!essay.length||essay.some(x=>!x.vi.trim()))return null;
 return {id:"custom-"+Date.now().toString(36)+Math.random().toString(36).slice(2,7),task,type:item.type|| (task==="Task 1"?"Academic report":"Essay"),topic:item.topic||"General",title:item.title,question:item.question,source:"Nhập hàng loạt",sourceUrl:item.sourceUrl||"",sourceType:"personal",time:task==="Task 1"?20:40,visual:item.visual||"",visualData:item.visualData||"",essay,custom:true,createdAt:new Date().toISOString()};
}
